import { parseDate } from "./date";
import { cloneScenario } from "./scenario";
import type { Faction, Scenario, WarDeclaration } from "./types";

/** Marks war declarations generated by applyFactions (no Barbarossa-style surprise for these). */
export const FACTION_WAR_NOTE = "陣営変更による参戦";

const opposite = (a: Faction, b: Faction) => a !== "neutral" && b !== "neutral" && a !== b;

/**
 * Rebuilds the war declarations of `scenario` after factions were changed relative to `preset`
 * (user requirement: factions can be changed per country, with war declarations handled sensibly).
 *
 * 1. Every historical pair (a declares on b) is kept only if a and b are now in opposite factions: same-faction
 *    pairs and pairs with a neutral are dropped (a neutral stays out of the war, even one attacked historically).
 * 2. Countries that join by the faction rule: those whose faction differs from the preset, and belligerents left
 *    without any kept pair although they had one. Their entry date is their first historical war date (either
 *    side, even if that pair was dropped); a country that never entered a war enters on the first war date of the
 *    scenario.
 * 3. Such a country goes to war with every country of the opposite faction that enters the war at some point, on
 *    the later of the two entry dates. The joining country is the one that declares (also on countries that enter
 *    later, e.g. by being invaded: "スペインがデンマーク王国・ノルウェー王国に宣戦布告"); of two joining countries,
 *    the one processed first.
 *
 * With the preset's factions the war list is returned unchanged, so the historical results stay identical.
 */
export function applyFactions(preset: Scenario, scenario: Scenario): Scenario {
  const out = cloneScenario(scenario);
  const faction = (t: string): Faction => out.countries[t]?.faction ?? "neutral";
  const ms = (d: string) => parseDate(d);

  const entry = new Map<string, string>();
  const setEntry = (t: string, d: string) => {
    const cur = entry.get(t);
    if (cur === undefined || ms(d) < ms(cur)) entry.set(t, d);
  };
  for (const w of preset.wars) for (const t of [...w.a, ...w.b]) setEntry(t, w.date);

  const hadPair = new Set<string>(), keptPair = new Set<string>();
  const pairKey = (x: string, y: string) => (x < y ? `${x}|${y}` : `${y}|${x}`);
  // Pairs already at war through a kept historical declaration (not generated again).
  const done = new Set<string>();
  const wars: WarDeclaration[] = [];
  for (const w of scenario.wars) {
    for (const t of [...w.a, ...w.b]) hadPair.add(t);
    // Keep the declaration's grouping where possible: each attacker with the defenders it still opposes.
    const groups = new Map<string, { a: string[]; b: string[] }>();
    for (const a of w.a) {
      const bs = w.b.filter((b) => opposite(faction(a), faction(b)));
      if (!bs.length) continue;
      const key = bs.join(",");
      const g = groups.get(key) ?? { a: [], b: bs };
      g.a.push(a);
      groups.set(key, g);
      keptPair.add(a);
      for (const b of bs) {
        keptPair.add(b);
        done.add(pairKey(a, b));
      }
    }
    for (const g of groups.values()) wars.push({ ...w, a: g.a, b: g.b });
  }

  const tags = Object.keys(out.countries);
  const joining = tags.filter((t) => faction(t) !== "neutral" &&
    (faction(t) !== (preset.countries[t]?.faction ?? "neutral") || (hadPair.has(t) && !keptPair.has(t))));
  if (joining.length) {
    const firstDate = [...scenario.wars.map((w) => w.date)].sort((p, q) => ms(p) - ms(q))[0] ?? out.wars[0]?.date;
    if (firstDate) for (const t of joining) if (!entry.has(t)) entry.set(t, firstDate);
    // Generated declarations, grouped by (date, joining country) so that the news lists the enemies together.
    const generated = new Map<string, WarDeclaration>();
    for (const c of joining) {
      for (const d of tags) {
        if (!opposite(faction(c), faction(d)) || !entry.has(d)) continue;
        const key = pairKey(c, d);
        if (done.has(key)) continue;
        done.add(key);
        // Each pair once (`done`); with both joining on the same date, the one processed first declares.
        const ec = ms(entry.get(c)!), ed = ms(entry.get(d)!);
        const date = ed > ec ? entry.get(d)! : entry.get(c)!;
        const gk = `${date}|${c}`;
        const g = generated.get(gk) ?? { date, a: [c], b: [], note: FACTION_WAR_NOTE };
        g.b.push(d);
        generated.set(gk, g);
      }
    }
    wars.push(...generated.values());
  }
  out.wars = wars.sort((p, q) => ms(p.date) - ms(q.date));
  return out;
}

/**
 * Sets a country's faction in the setup; its dependent countries (CountrySetup.overlord: the Dutch East Indies,
 * the British dominions, Free France), and theirs, follow (user requirement). Each country is changed once.
 */
export function setFaction(scenario: Scenario, tag: string, f: Faction): void {
  const seen = new Set<string>();
  const follow = (t: string) => {
    if (seen.has(t) || !scenario.countries[t]) return;
    seen.add(t);
    scenario.countries[t].faction = f;
    for (const [d, c] of Object.entries(scenario.countries)) if (c.overlord === t) follow(d);
  };
  follow(tag);
}
